package epam.arsen.burko.gym.service;

import epam.arsen.burko.gym.entity.Trainee;
import epam.arsen.burko.gym.entity.Trainer;
import epam.arsen.burko.gym.exception.TraineeNotFoundException;
import epam.arsen.burko.gym.repository.TraineeRepository;
import epam.arsen.burko.gym.repository.TrainerRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

@Service
@Slf4j
@RequiredArgsConstructor
public class TraineeService {
    private final TraineeRepository traineeRepository;
    private final TrainerRepository trainerRepository;
    private final IdentityGenerationService identityService;
    private final AuthService auth;

    @Transactional
    public Trainee createTrainee(String firstName, String lastName, LocalDate dateOfBirth, String address) {
        log.info("Creating new trainee profile for: {} {}", firstName, lastName);

        Trainee trainee = new Trainee();
        trainee.setFirstName(firstName);
        trainee.setLastName(lastName);
        trainee.setUsername(identityService.generateUsername(firstName, lastName));
        trainee.setPassword(identityService.generatePassword());
        trainee.setIsActive(true);
        trainee.setDateOfBirth(dateOfBirth);
        trainee.setAddress(address);

        log.info("Successfully created trainee with username: {}", trainee.getUsername());
        return traineeRepository.save(trainee);
    }

    @Transactional
    public void updateTrainers(String username, String password, Set<Long> trainerIds) {
        log.info("Updating trainer list for trainee: {}", username);
        auth.validate(username, password);
        Trainee trainee = traineeRepository.findByUsername(username).orElseThrow();
        trainee.setTrainers(new HashSet<>(trainerRepository.findAllById(trainerIds)));
        log.info("Successfully updated trainer list for trainee: {}", username);
    }

    public Trainee get(String username, String password) {
        log.info("Fetching profile for trainee: {}", username);
        auth.validate(username, password);
        return traineeRepository.findByUsername(username).orElseThrow();
    }

    @Transactional
    public Trainee updateProfile(String username, String password, Trainee updated) {
        log.info("Updating profile for trainee: {}", username);
        auth.validate(username, password);

        Trainee trainee = traineeRepository.findByUsername(username).orElseThrow();

        trainee.setFirstName(updated.getFirstName());
        trainee.setLastName(updated.getLastName());
        trainee.setDateOfBirth(updated.getDateOfBirth());
        trainee.setAddress(updated.getAddress());
        log.info("Successfully updated profile for trainee: {}", username);
        return trainee;
    }

    @Transactional
    public void changePassword(String username, String oldPassword, String newPassword) {
        log.info("Processing password change for trainee: {}", username);
        auth.validate(username, oldPassword);
        Trainee trainee = traineeRepository.findByUsername(username).orElseThrow();
        trainee.setPassword(newPassword);
        log.info("Successfully changed password for trainee: {}", username);
    }

    @Transactional
    public void toggleStatus(String username, String password, boolean isActive) {
        log.info("Toggling active status for trainee: {} to {}", username, isActive);
        auth.validate(username, password);

        Trainee trainee = traineeRepository.findByUsername(username)
                .orElseThrow(() -> new TraineeNotFoundException("Trainee not found"));
        trainee.setIsActive(isActive);

        traineeRepository.save(trainee);
        log.info("Successfully updated status for trainee: {}", username);
    }

    @Transactional
    public void deleteTrainee(String username, String password) {
        log.info("Attempting to delete trainee profile: {}", username);
        auth.validate(username, password);
        Trainee trainee = traineeRepository.findByUsername(username)
                .orElseThrow(() -> new TraineeNotFoundException("Trainee not found"));
        traineeRepository.delete(trainee);
        log.info("Successfully deleted trainee profile: {}", username);
    }

    @Transactional
    public List<Trainer> getUnassigned(String username, String password) {
        log.info("Fetching unassigned trainers for trainee: {}", username);
        auth.validate(username, password);

        return trainerRepository.findTrainersNotAssignedToTrainee(username);
    }
}

package epam.arsen.burko.gym.service;

import epam.arsen.burko.gym.entity.Trainee;
import epam.arsen.burko.gym.entity.Trainer;
import epam.arsen.burko.gym.exception.TraineeNotFoundException;
import epam.arsen.burko.gym.repository.TraineeRepository;
import epam.arsen.burko.gym.repository.TrainerRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

@Service
@Slf4j
@RequiredArgsConstructor
public class TraineeService {
    private final TraineeRepository traineeRepository;
    private final TrainerRepository trainerRepository;
    private final IdentityGenerationService identityService;
    private final AuthService auth;

    @Transactional
    public Trainee createTrainee(String firstName, String lastName, LocalDate dateOfBirth, String address) {
        log.info("Creating new trainee profile for: {} {}", firstName, lastName);

        Trainee trainee = new Trainee();
        trainee.setFirstName(firstName);
        trainee.setLastName(lastName);
        trainee.setUsername(identityService.generateUsername(firstName, lastName));
        trainee.setPassword(identityService.generatePassword());
        trainee.setIsActive(true);
        trainee.setDateOfBirth(dateOfBirth);
        trainee.setAddress(address);

        log.info("Successfully created trainee with username: {}", trainee.getUsername());
        return traineeRepository.save(trainee);
    }

    @Transactional
    public void updateTrainers(String username, String password, Set<Long> trainerIds) {
        log.info("Updating trainer list for trainee: {}", username);
        auth.validate(username, password);
        Trainee trainee = traineeRepository.findByUsername(username)
                .orElseThrow(() -> new TraineeNotFoundException("Trainee not found"));
        trainee.setTrainers(new HashSet<>(trainerRepository.findAllById(trainerIds)));
        log.info("Successfully updated trainer list for trainee: {}", username);
    }

    public Trainee get(String username, String password) {
        log.info("Fetching profile for trainee: {}", username);
        auth.validate(username, password);
        return traineeRepository.findByUsername(username)
                .orElseThrow(() -> new TraineeNotFoundException("Trainee not found"));
    }

    @Transactional
    public Trainee updateProfile(String username, String password, Trainee updated) {
        log.info("Updating profile for trainee: {}", username);
        auth.validate(username, password);

        Trainee trainee = traineeRepository.findByUsername(username)
                .orElseThrow(() -> new TraineeNotFoundException("Trainee not found"));

        trainee.setFirstName(updated.getFirstName());
        trainee.setLastName(updated.getLastName());
        trainee.setDateOfBirth(updated.getDateOfBirth());
        trainee.setAddress(updated.getAddress());
        log.info("Successfully updated profile for trainee: {}", username);
        return trainee;
    }

    @Transactional
    public void changePassword(String username, String oldPassword, String newPassword) {
        log.info("Processing password change for trainee: {}", username);
        auth.validate(username, oldPassword);
        Trainee trainee = traineeRepository.findByUsername(username)
                .orElseThrow(() -> new TraineeNotFoundException("Trainee not found"));
        trainee.setPassword(newPassword);
        log.info("Successfully changed password for trainee: {}", username);
    }

    @Transactional
    public void toggleStatus(String username, String password, boolean isActive) {
        log.info("Toggling active status for trainee: {} to {}", username, isActive);
        auth.validate(username, password);

        Trainee trainee = traineeRepository.findByUsername(username)
                .orElseThrow(() -> new TraineeNotFoundException("Trainee not found"));
        trainee.setIsActive(isActive);

        traineeRepository.save(trainee);
        log.info("Successfully updated status for trainee: {}", username);
    }

    @Transactional
    public void deleteTrainee(String username, String password) {
        log.info("Attempting to delete trainee profile: {}", username);
        auth.validate(username, password);
        Trainee trainee = traineeRepository.findByUsername(username)
                .orElseThrow(() -> new TraineeNotFoundException("Trainee not found"));
        traineeRepository.delete(trainee);
        log.info("Successfully deleted trainee profile: {}", username);
    }

    @Transactional
    public List<Trainer> getUnassigned(String username, String password) {
        log.info("Fetching unassigned trainers for trainee: {}", username);
        auth.validate(username, password);

        return trainerRepository.findTrainersNotAssignedToTrainee(username);
    }
}

package epam.arsen.burko.gym.config;

import epam.arsen.burko.gym.security.CustomUserDetailsService;
import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.security.authentication.dao.DaoAuthenticationProvider;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.web.cors.CorsConfiguration;
import org.springframework.web.cors.CorsConfigurationSource;
import org.springframework.web.cors.UrlBasedCorsConfigurationSource;

import java.util.Arrays;

@Configuration
@EnableWebSecurity
@RequiredArgsConstructor
public class SecurityConfiguration {

    private final CustomUserDetailsService customUserDetailsService;

    @Bean
    public PasswordEncoder passwordEncoder() {
        // BCryptPasswordEncoder uses salt and hashing for secure password storage
        return new org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder();
    }

    @Bean
    public DaoAuthenticationProvider authenticationProvider() {
        DaoAuthenticationProvider authProvider = new DaoAuthenticationProvider();
        authProvider.setUserDetailsService(customUserDetailsService);
        authProvider.setPasswordEncoder(passwordEncoder());
        return authProvider;
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
                .csrf(csrf -> csrf.disable())
                .httpBasic(basic -> {})
                .authorizeHttpRequests(authz -> authz
                        // Allow registration endpoints without authentication
                        .requestMatchers(HttpMethod.POST, "/trainees/register").permitAll()
                        .requestMatchers(HttpMethod.POST, "/trainers/register").permitAll()
                        // Allow auth endpoints (login) without authentication
                        .requestMatchers(HttpMethod.GET, "/auth/login").permitAll()
                        // Allow public endpoints
                        .requestMatchers(HttpMethod.GET, "/actuator/**").permitAll()
                        .requestMatchers("/actuator/health").permitAll()
                        // Allow swagger/api-docs endpoints
                        .requestMatchers("/swagger-ui/**", "/v2/api-docs", "/swagger-resources/**").permitAll()
                        // Require authentication for all other endpoints
                        .anyRequest().authenticated()
                )
                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .logout(logout -> logout
                        .logoutUrl("/auth/logout")
                        .logoutSuccessHandler((request, response, authentication) -> {
                            response.setStatus(200);
                        })
                        .permitAll()
                )
                .authenticationProvider(authenticationProvider())
                .cors(cors -> {});

        return http.build();
    }

    @Bean
    public CorsConfigurationSource corsConfigurationSource() {
        CorsConfiguration configuration = new CorsConfiguration();
        configuration.setAllowedOrigins(Arrays.asList("*"));
        configuration.setAllowedMethods(Arrays.asList("GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"));
        configuration.setAllowedHeaders(Arrays.asList("*"));
        configuration.setAllowCredentials(false);
        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        source.registerCorsConfiguration("/**", configuration);
        return source;
    }
}

package epam.arsen.burko.gym.config;

import epam.arsen.burko.gym.security.CustomUserDetailsService;
import epam.arsen.burko.gym.security.JwtAuthenticationFilter;
import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.security.authentication.dao.DaoAuthenticationProvider;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
import org.springframework.web.cors.CorsConfiguration;
import org.springframework.web.cors.CorsConfigurationSource;
import org.springframework.web.cors.UrlBasedCorsConfigurationSource;

import java.util.Arrays;

@Configuration
@EnableWebSecurity
@RequiredArgsConstructor
public class SecurityConfiguration {

    private final CustomUserDetailsService customUserDetailsService;
    private final JwtAuthenticationFilter jwtAuthenticationFilter;

    @Bean
    public PasswordEncoder passwordEncoder() {
        // BCryptPasswordEncoder uses salt and hashing for secure password storage
        return new org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder();
    }

    @Bean
    public DaoAuthenticationProvider authenticationProvider() {
        DaoAuthenticationProvider authProvider = new DaoAuthenticationProvider();
        authProvider.setUserDetailsService(customUserDetailsService);
        authProvider.setPasswordEncoder(passwordEncoder());
        return authProvider;
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
                .csrf(csrf -> csrf.disable())
                .authorizeHttpRequests(authz -> authz
                        // Allow registration endpoints without authentication
                        .requestMatchers(HttpMethod.POST, "/trainees/register").permitAll()
                        .requestMatchers(HttpMethod.POST, "/trainers/register").permitAll()
                        // Allow auth login endpoint without authentication
                        .requestMatchers(HttpMethod.GET, "/auth/login").permitAll()
                        // Allow public endpoints
                        .requestMatchers(HttpMethod.GET, "/actuator/**").permitAll()
                        .requestMatchers("/actuator/health").permitAll()
                        // Allow swagger/api-docs endpoints
                        .requestMatchers("/swagger-ui/**", "/v2/api-docs", "/swagger-resources/**").permitAll()
                        // Require authentication for all other endpoints
                        .anyRequest().authenticated()
                )
                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .logout(logout -> logout
                        .logoutUrl("/auth/logout")
                        .logoutSuccessHandler((request, response, authentication) -> {
                            response.setStatus(200);
                        })
                        .permitAll()
                )
                .authenticationProvider(authenticationProvider())
                .cors(cors -> cors.configurationSource(corsConfigurationSource()))
                .addFilterBefore(jwtAuthenticationFilter, UsernamePasswordAuthenticationFilter.class);

        return http.build();
    }

    @Bean
    public CorsConfigurationSource corsConfigurationSource() {
        CorsConfiguration configuration = new CorsConfiguration();
        configuration.setAllowedOrigins(Arrays.asList("http://localhost:3000", "http://localhost:8080", "*"));
        configuration.setAllowedMethods(Arrays.asList("GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"));
        configuration.setAllowedHeaders(Arrays.asList("*"));
        configuration.setExposedHeaders(Arrays.asList("Authorization", "Content-Type"));
        configuration.setAllowCredentials(false);
        configuration.setMaxAge(3600L);
        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        source.registerCorsConfiguration("/**", configuration);
        return source;
    }
}

package epam.arsen.burko.gym.controller;

import epam.arsen.burko.gym.dto.ChangeLoginRequest;
import epam.arsen.burko.gym.service.AuthService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import io.swagger.annotations.Api;
import io.swagger.annotations.ApiOperation;
import io.swagger.annotations.ApiParam;
import io.swagger.annotations.ApiResponse;
import io.swagger.annotations.ApiResponses;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;

@Api(tags = "Authentication")
@RestController
@RequestMapping("/auth")
@RequiredArgsConstructor
@Validated
@Slf4j
public class AuthController {

    private final AuthService authService;

    @GetMapping("/login")
    @ApiOperation(value = "Login")
    @ApiResponses({
            @ApiResponse(code = 200, message = "OK"),
            @ApiResponse(code = 400, message = "Validation Failed"),
            @ApiResponse(code = 401, message = "Unauthorized"),
            @ApiResponse(code = 404, message = "User Not Found"),
            @ApiResponse(code = 423, message = "User Locked - Too many failed attempts")
    })
    public ResponseEntity<Void> login(
            @RequestParam @ApiParam(required = true, value = "Username") @NotBlank(message = "Username is required") String username,
            @RequestParam @ApiParam(required = true, value = "Password") @NotBlank(message = "Password is required") String password
    ) {
        log.info("Login attempt for user: {}", username);
        authService.validate(username, password);
        log.info("Login successful for user: {}", username);
        return ResponseEntity.ok().build();
    }

    @PostMapping("/logout")
    @ApiOperation(value = "Logout")
    @ApiResponses({
            @ApiResponse(code = 200, message = "OK"),
            @ApiResponse(code = 401, message = "Unauthorized")
    })
    public ResponseEntity<Void> logout() {
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
        if (authentication != null) {
            log.info("Logout request for user: {}", authentication.getName());
            SecurityContextHolder.clearContext();
            log.info("User logged out successfully: {}", authentication.getName());
        }
        return ResponseEntity.ok().build();
    }

    @PutMapping("/login")
    @ApiOperation(value = "Change Login Password")
    @ApiResponses({
            @ApiResponse(code = 200, message = "OK"),
            @ApiResponse(code = 400, message = "Validation Failed"),
            @ApiResponse(code = 401, message = "Unauthorized"),
            @ApiResponse(code = 404, message = "User Not Found"),
            @ApiResponse(code = 423, message = "User Locked - Too many failed attempts")
    })
    public ResponseEntity<Void> changeLogin(@Valid @RequestBody ChangeLoginRequest request) {
        log.info("Password change request for user: {}", request.username());
        authService.changePassword(request.username(), request.oldPassword(), request.newPassword());
        log.info("Password changed successfully for user: {}", request.username());
        return ResponseEntity.ok().build();
    }
}

package epam.arsen.burko.gym.controller;

import epam.arsen.burko.gym.dto.ChangeLoginRequest;
import epam.arsen.burko.gym.dto.LoginResponse;
import epam.arsen.burko.gym.service.AuthService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import io.swagger.annotations.Api;
import io.swagger.annotations.ApiOperation;
import io.swagger.annotations.ApiParam;
import io.swagger.annotations.ApiResponse;
import io.swagger.annotations.ApiResponses;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;

@Api(tags = "Authentication")
@RestController
@RequestMapping("/auth")
@RequiredArgsConstructor
@Validated
@Slf4j
public class AuthController {

    private final AuthService authService;

    @GetMapping("/login")
    @ApiOperation(value = "Login and get JWT token")
    @ApiResponses({
            @ApiResponse(code = 200, message = "OK - Returns JWT token"),
            @ApiResponse(code = 400, message = "Validation Failed"),
            @ApiResponse(code = 401, message = "Unauthorized"),
            @ApiResponse(code = 404, message = "User Not Found"),
            @ApiResponse(code = 423, message = "User Locked - Too many failed attempts")
    })
    public ResponseEntity<LoginResponse> login(
            @RequestParam @ApiParam(required = true, value = "Username") @NotBlank(message = "Username is required") String username,
            @RequestParam @ApiParam(required = true, value = "Password") @NotBlank(message = "Password is required") String password
    ) {
        log.info("Login attempt for user: {}", username);
        LoginResponse response = authService.authenticate(username, password);
        log.info("Login successful for user: {}", username);
        return ResponseEntity.ok(response);
    }

    @PostMapping("/logout")
    @ApiOperation(value = "Logout - invalidates current session")
    @ApiResponses({
            @ApiResponse(code = 200, message = "OK"),
            @ApiResponse(code = 401, message = "Unauthorized")
    })
    public ResponseEntity<Void> logout() {
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
        if (authentication != null) {
            log.info("Logout request for user: {}", authentication.getName());
            SecurityContextHolder.clearContext();
            log.info("User logged out successfully: {}", authentication.getName());
        }
        return ResponseEntity.ok().build();
    }

    @PutMapping("/login")
    @ApiOperation(value = "Change Login Password")
    @ApiResponses({
            @ApiResponse(code = 200, message = "OK"),
            @ApiResponse(code = 400, message = "Validation Failed"),
            @ApiResponse(code = 401, message = "Unauthorized"),
            @ApiResponse(code = 404, message = "User Not Found"),
            @ApiResponse(code = 423, message = "User Locked - Too many failed attempts")
    })
    public ResponseEntity<Void> changeLogin(@Valid @RequestBody ChangeLoginRequest request) {
        log.info("Password change request for user: {}", request.username());
        authService.changePassword(request.username(), request.oldPassword(), request.newPassword());
        log.info("Password changed successfully for user: {}", request.username());
        return ResponseEntity.ok().build();
    }
}

package epam.arsen.burko.gym.dto;

public record LoginResponse(
        String username,
        String token,
        String tokenType
) {
    public LoginResponse(String username, String token) {
        this(username, token, "Bearer");
    }
}

package epam.arsen.burko.gym.security;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Component;
import org.springframework.util.StringUtils;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;
import java.util.Collections;

@Component
@RequiredArgsConstructor
@Slf4j
public class JwtAuthenticationFilter extends OncePerRequestFilter {

    private final JwtTokenProvider jwtTokenProvider;

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain)
            throws ServletException, IOException {
        try {
            String jwt = extractTokenFromRequest(request);
            if (StringUtils.hasText(jwt) && jwtTokenProvider.validateToken(jwt)) {
                String username = jwtTokenProvider.getUsernameFromToken(jwt);
                log.debug("Setting user '{}' in security context from JWT token", username);
                UsernamePasswordAuthenticationToken authentication = new UsernamePasswordAuthenticationToken(
                        username, null, Collections.singletonList(new SimpleGrantedAuthority("ROLE_USER")));
                SecurityContextHolder.getContext().setAuthentication(authentication);
            }
        } catch (Exception ex) {
            log.warn("Cannot set user authentication from JWT token: {}", ex.getMessage());
        }

        filterChain.doFilter(request, response);
    }

    private String extractTokenFromRequest(HttpServletRequest request) {
        String bearerToken = request.getHeader("Authorization");
        if (StringUtils.hasText(bearerToken) && bearerToken.startsWith("Bearer ")) {
            log.debug("Extracted Bearer token from Authorization header");
            return bearerToken.substring(7);
        }
        return null;
    }
}

package epam.arsen.burko.gym.security;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import io.jsonwebtoken.security.Keys;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.SecretKey;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;

@Component
@Slf4j
public class JwtTokenProvider {

    @Value("${jwt.secret:MyVerySecureSecretKeyForJWTTokenGenerationAndValidation1234567890123456}")
    private String jwtSecret;

    @Value("${jwt.expiration:3600000}")
    private long jwtExpirationMs;

    public String generateToken(String username) {
        log.debug("Generating JWT token for user: {}", username);
        Map<String, Object> claims = new HashMap<>();
        return createToken(claims, username);
    }

    private String createToken(Map<String, Object> claims, String subject) {
        SecretKey key = Keys.hmacShaKeyFor(jwtSecret.getBytes());
        Date now = new Date();
        Date expiryDate = new Date(now.getTime() + jwtExpirationMs);

        String token = Jwts.builder()
                .setClaims(claims)
                .setSubject(subject)
                .setIssuedAt(now)
                .setExpiration(expiryDate)
                .signWith(key, SignatureAlgorithm.HS512)
                .compact();

        log.debug("JWT token generated successfully for user: {}", subject);
        return token;
    }

    public String getUsernameFromToken(String token) {
        log.debug("Extracting username from JWT token");
        return getClaims(token).getSubject();
    }

    public boolean validateToken(String token) {
        try {
            log.debug("Validating JWT token");
            getClaims(token);
            log.debug("JWT token is valid");
            return true;
        } catch (Exception ex) {
            log.warn("Invalid JWT token: {}", ex.getMessage());
            return false;
        }
    }

    private Claims getClaims(String token) {
        SecretKey key = Keys.hmacShaKeyFor(jwtSecret.getBytes());
        return Jwts.parser()
                .verifyWith(key)
                .build()
                .parseSignedClaims(token)
                .getPayload();
    }

    public boolean isTokenExpired(String token) {
        try {
            Claims claims = getClaims(token);
            return claims.getExpiration().before(new Date());
        } catch (Exception ex) {
            log.warn("Error checking token expiration: {}", ex.getMessage());
            return true;
        }
    }
}

package epam.arsen.burko.gym.service;

import epam.arsen.burko.gym.entity.User;
import epam.arsen.burko.gym.exception.InvalidPasswordException;
import epam.arsen.burko.gym.exception.UserLockedException;
import epam.arsen.burko.gym.exception.UserNotFoundException;
import epam.arsen.burko.gym.repository.UserRepository;
import epam.arsen.burko.gym.security.BruteForceProtectionService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Slf4j
@RequiredArgsConstructor
public class AuthService {
    private final UserRepository userRepository;
    private final PasswordEncoder passwordEncoder;
    private final BruteForceProtectionService bruteForceProtectionService;

    public void validate(String username, String password) {
        log.debug("Attempting to authenticate user: {}", username);

        // Check if user is locked due to brute force protection
        if (bruteForceProtectionService.isUserLocked(username)) {
            log.warn("Login attempt for locked user: {}", username);
            throw new UserLockedException("User account is temporarily locked due to too many failed login attempts. Please try again in 5 minutes.");
        }

        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new UserNotFoundException("User not found"));

        if (!passwordEncoder.matches(password, user.getPassword())) {
            bruteForceProtectionService.recordFailedLogin(username);
            throw new InvalidPasswordException("Invalid password");
        }

        bruteForceProtectionService.recordSuccessfulLogin(username);
        log.debug("User '{}' successfully authenticated", username);
    }

    @Transactional
    public void changePassword(String username, String oldPassword, String newPassword) {
        log.info("Processing password change for user: {}", username);
        validate(username, oldPassword);
        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new UserNotFoundException("User not found"));
        user.setPassword(passwordEncoder.encode(newPassword));
        userRepository.save(user);
        log.info("Password successfully changed for user: {}", username);
    }
}

package epam.arsen.burko.gym.service;

import epam.arsen.burko.gym.dto.LoginResponse;
import epam.arsen.burko.gym.entity.User;
import epam.arsen.burko.gym.exception.InvalidPasswordException;
import epam.arsen.burko.gym.exception.UserLockedException;
import epam.arsen.burko.gym.exception.UserNotFoundException;
import epam.arsen.burko.gym.repository.UserRepository;
import epam.arsen.burko.gym.security.BruteForceProtectionService;
import epam.arsen.burko.gym.security.JwtTokenProvider;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Slf4j
@RequiredArgsConstructor
public class AuthService {
    private final UserRepository userRepository;
    private final PasswordEncoder passwordEncoder;
    private final BruteForceProtectionService bruteForceProtectionService;
    private final JwtTokenProvider jwtTokenProvider;

    public LoginResponse authenticate(String username, String password) {
        log.debug("Attempting to authenticate user: {}", username);

        // Check if user is locked due to brute force protection
        if (bruteForceProtectionService.isUserLocked(username)) {
            log.warn("Login attempt for locked user: {}", username);
            throw new UserLockedException("User account is temporarily locked due to too many failed login attempts. Please try again in 5 minutes.");
        }

        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new UserNotFoundException("User not found"));

        if (!passwordEncoder.matches(password, user.getPassword())) {
            bruteForceProtectionService.recordFailedLogin(username);
            throw new InvalidPasswordException("Invalid password");
        }

        bruteForceProtectionService.recordSuccessfulLogin(username);
        String token = jwtTokenProvider.generateToken(username);
        log.debug("User '{}' successfully authenticated and JWT token generated", username);
        return new LoginResponse(username, token);
    }

    public void validate(String username, String password) {
        log.debug("Attempting to authenticate user: {}", username);

        // Check if user is locked due to brute force protection
        if (bruteForceProtectionService.isUserLocked(username)) {
            log.warn("Login attempt for locked user: {}", username);
            throw new UserLockedException("User account is temporarily locked due to too many failed login attempts. Please try again in 5 minutes.");
        }

        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new UserNotFoundException("User not found"));

        if (!passwordEncoder.matches(password, user.getPassword())) {
            bruteForceProtectionService.recordFailedLogin(username);
            throw new InvalidPasswordException("Invalid password");
        }

        bruteForceProtectionService.recordSuccessfulLogin(username);
        log.debug("User '{}' successfully authenticated", username);
    }

    @Transactional
    public void changePassword(String username, String oldPassword, String newPassword) {
        log.info("Processing password change for user: {}", username);
        validate(username, oldPassword);
        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new UserNotFoundException("User not found"));
        user.setPassword(passwordEncoder.encode(newPassword));
        userRepository.save(user);
        log.info("Password successfully changed for user: {}", username);
    }
}

